	arrayCache.Append(map[string]any{
		"symbol": "BTC/USDT",
		"data":   6,
	})
	arrayCache.Append(map[string]any{
		"symbol": "BTC/USDT",
		"data":   7,
	})
	arrayCache.Append(map[string]any{
		"symbol": "BTC/USDT",
		"data":   8,
	})
	Assert(Equals(arrayCache, []any{map[string]any{
		"symbol": "BTC/USDT",
		"data":   6,
	}, map[string]any{
		"symbol": "BTC/USDT",
		"data":   7,
	}, map[string]any{
		"symbol": "BTC/USDT",
		"data":   8,
	}}))
	arrayCache.Clear()
	arrayCache.Append(map[string]any{
		"symbol": "BTC/USDT",
		"data":   1,
	})
	Assert(Equals(arrayCache, []any{map[string]any{
		"symbol": "BTC/USDT",
		"data":   1,
	}}))

